/* TEAM CODE (owner: Jack - audio input and SD storage) - written by the BJT2 team, not generated by STM32CubeMX. */
/* Authors: Jack; Brendon (integrator) rewrote the header parser - wav_parse_header() and its RIFF chunk helpers (28 Oct 2026). */
/* WAV headers: build the 44-byte header of our own recordings, and read the
 * header of any PCM WAV file (ours, the effect files, PC-made ones).
 *
 * A WAV file is a RIFF file: a 12-byte RIFF header ("RIFF", the size of the
 * rest of the file, "WAVE"), then chunks. Each chunk is an 8-byte chunk
 * header (a 4-letter id and a 32-bit size) and then that many bytes, plus
 * one pad byte when the size is odd. The "fmt " chunk says how the samples
 * are stored; the "data" chunk holds the samples. Every number is
 * little-endian (lowest byte first).
 *
 * No task of its own: everything runs inside JackStorageTask.
 *   - wav_build_header(): jack_audio_sd.c, at record start (data size 0)
 *     and at the end of a recording (the real size).
 *   - wav_parse_header(): fx_job.c, on the first 512 bytes of a file: the
 *     facts of a file to play (at play start, and before its effect files
 *     are checked or made) and the check of an effect file (at play start,
 *     and in the background).
 * Pure logic on byte arrays, no RTOS, HAL or card (tests:
 * Tests/test_wav_storage.c). CR3 (a requirement from our Prototype Design 2,
 * PD5b_Jack/VERIFICATION.md Part 5) = support WAV/PCM. */
#include "wav_storage.h"
#include <string.h>

/* RIFF layout the header parser relies on. */
#define WAV_RIFF_HEADER_SIZE     12U          /* "RIFF" <size> "WAVE" */
#define WAV_CHUNK_HEADER_SIZE    8U           /* <4-character id> <32-bit size> */
#define WAV_FMT_MIN_SIZE         16U          /* the fields every PCM fmt chunk has */
#define WAV_FMT_EXTENSIBLE_SIZE  40U          /* + cbSize, valid bits, channel mask, sub-format */
#define WAV_FMT_SUBFORMAT_OFFSET 24U          /* sub-format GUID inside an EXTENSIBLE fmt chunk */
#define WAV_FORMAT_PCM           0x0001U
#define WAV_FORMAT_EXTENSIBLE    0xFFFEU
#define WAV_SIZE_UNKNOWN         0xFFFFFFFFU  /* size a streaming writer leaves when it cannot seek back */

/* KSDATAFORMAT_SUBTYPE_PCM {00000001-0000-0010-8000-00AA00389B71} in file
 * byte order: the first three groups are stored little-endian, the last two
 * as plain bytes. (A GUID is a 16-byte ID; this one means plain PCM.) */
static const uint8_t s_subformat_pcm[16] =
{
    0x01U, 0x00U, 0x00U, 0x00U, 0x00U, 0x00U, 0x10U, 0x00U,
    0x80U, 0x00U, 0x00U, 0xAAU, 0x00U, 0x38U, 0x9BU, 0x71U
};

/* Little-endian helpers - WAV format is always little-endian regardless
 * of host/target byte order, so we write byte-by-byte rather than relying
 * on the compiler's native endianness. */
static void put_u32_le(uint8_t *p, uint32_t v)
{
    p[0] = (uint8_t)(v & 0xFFU);
    p[1] = (uint8_t)((v >> 8) & 0xFFU);
    p[2] = (uint8_t)((v >> 16) & 0xFFU);
    p[3] = (uint8_t)((v >> 24) & 0xFFU);
}

static uint32_t get_u32_le(const uint8_t *p)
{
    return (uint32_t)p[0] |
           ((uint32_t)p[1] << 8) |
           ((uint32_t)p[2] << 16) |
           ((uint32_t)p[3] << 24);
}

static void put_u16_le(uint8_t *p, uint16_t v)
{
    p[0] = (uint8_t)(v & 0xFFU);
    p[1] = (uint8_t)((v >> 8) & 0xFFU);
}

static uint16_t get_u16_le(const uint8_t *p)
{
    return (uint16_t)((uint16_t)p[0] | ((uint16_t)p[1] << 8));
}

static int bits_per_sample_valid(uint16_t bits)
{
    return (bits == 8U) || (bits == 16U) || (bits == 24U) || (bits == 32U);
}

static int channels_valid(uint16_t channels)
{
    return (channels == 1U) || (channels == 2U);
}

/* The canonical 44-byte header (the byte offsets are in the code below):
 *   RIFF header, bytes 0-11:  "RIFF", the number of bytes after this field
 *                             (36 + data size), "WAVE";
 *   fmt chunk, bytes 12-35:   "fmt ", its size (16), format 1 = PCM (plain
 *                             samples), channels, sample rate, byte rate
 *                             (bytes per second), block align (bytes per
 *                             sample frame), bits per sample;
 *   data chunk, bytes 36-43:  "data", the size of the samples in bytes;
 *   the samples from byte 44.
 * Our recordings: 32000 Hz, 1 channel, 16 bits, so block align 2 and byte
 * rate 64000. The recorder writes this header twice: with data size 0 when
 * it starts, and with the real size at the end. */
storage_result_t wav_build_header(uint32_t sample_rate,
                                   uint16_t bits_per_sample,
                                   uint16_t num_channels,
                                   uint32_t data_size,
                                   uint8_t *out_buf,
                                   size_t out_len)
{
    if (out_buf == NULL)
    {
        return STORAGE_INVALID_ARG;
    }
    if (out_len < WAV_HEADER_SIZE)
    {
        return STORAGE_INVALID_ARG;
    }
    if (sample_rate == 0U)
    {
        return STORAGE_INVALID_ARG;
    }
    if (!bits_per_sample_valid(bits_per_sample))
    {
        return STORAGE_INVALID_ARG;
    }
    if (!channels_valid(num_channels))
    {
        return STORAGE_INVALID_ARG;
    }

    const uint16_t block_align = (uint16_t)(num_channels * (bits_per_sample / 8U));
    const uint32_t byte_rate = sample_rate * (uint32_t)block_align;

    /* RIFF chunk descriptor */
    memcpy(&out_buf[0], "RIFF", 4);
    put_u32_le(&out_buf[4], 36U + data_size);
    memcpy(&out_buf[8], "WAVE", 4);

    /* fmt subchunk */
    memcpy(&out_buf[12], "fmt ", 4);
    put_u32_le(&out_buf[16], 16U);           /* Subchunk1Size for PCM */
    put_u16_le(&out_buf[20], 1U);            /* AudioFormat = 1 (PCM) */
    put_u16_le(&out_buf[22], num_channels);
    put_u32_le(&out_buf[24], sample_rate);
    put_u32_le(&out_buf[28], byte_rate);
    put_u16_le(&out_buf[32], block_align);
    put_u16_le(&out_buf[34], bits_per_sample);

    /* data subchunk header */
    memcpy(&out_buf[36], "data", 4);
    put_u32_le(&out_buf[40], data_size);

    return STORAGE_OK;
}

/* Check one "fmt " chunk whose size bytes are all at p, and copy its format
 * fields into *fmt. Returns STORAGE_OK or STORAGE_CORRUPT. */
static storage_result_t parse_fmt_chunk(const uint8_t *p, uint32_t size, wav_header_t *fmt)
{
    if (size < WAV_FMT_MIN_SIZE)
    {
        /* Too short to describe any PCM format */
        return STORAGE_CORRUPT;
    }

    const uint16_t audio_format = get_u16_le(&p[0]);
    if (audio_format == WAV_FORMAT_EXTENSIBLE)
    {
        /* WAVE_FORMAT_EXTENSIBLE (ffmpeg and Windows write it for some PCM
         * files): the real format is the sub-format GUID that follows cbSize,
         * the valid-bits field and the channel mask. Only plain PCM is
         * accepted; a float or compressed sub-format is refused like a
         * non-PCM audio_format below. */
        if (size < WAV_FMT_EXTENSIBLE_SIZE)
        {
            return STORAGE_CORRUPT;
        }
        if (memcmp(&p[WAV_FMT_SUBFORMAT_OFFSET], s_subformat_pcm, sizeof(s_subformat_pcm)) != 0)
        {
            return STORAGE_CORRUPT;
        }
    }
    else if (audio_format != WAV_FORMAT_PCM)
    {
        /* Not PCM (e.g. compressed formats) - unsupported (CR3) */
        return STORAGE_CORRUPT;
    }

    const uint16_t num_channels = get_u16_le(&p[2]);
    const uint32_t sample_rate = get_u32_le(&p[4]);
    const uint16_t bits_per_sample = get_u16_le(&p[14]);

    if (!channels_valid(num_channels))
    {
        return STORAGE_CORRUPT;
    }
    if (sample_rate == 0U)
    {
        return STORAGE_CORRUPT;
    }
    if (!bits_per_sample_valid(bits_per_sample))
    {
        return STORAGE_CORRUPT;
    }

    fmt->sample_rate = sample_rate;
    fmt->bits_per_sample = bits_per_sample;
    fmt->num_channels = num_channels;
    return STORAGE_OK;
}

/* The chunk walk reached the chunk at pos without room left in buf for it
 * (or for its header) and has not met "data" yet. Which rejection that is
 * depends on whether buf holds the whole file (buf_len <= file_size). */
static storage_result_t walk_ran_out(size_t pos, size_t buf_len, uint32_t file_size)
{
    if (buf_len < file_size)
    {
        /* More of the file follows: "data" may come later, but not inside
         * the bytes the caller read, so the caller cannot stream it. */
        return STORAGE_NOT_FOUND;
    }
    if (pos == buf_len)
    {
        /* The last chunk ended exactly at the end of the file: the file
         * has no "data" chunk at all. */
        return STORAGE_CORRUPT;
    }
    /* The file ends inside a chunk header or a chunk: truncated header. */
    return STORAGE_INVALID_ARG;
}

/* Reading any PCM WAV header (wav_storage.h lists every return code):
 *   1. the first 12 bytes must be "RIFF" <size> "WAVE";
 *   2. walk the chunks in order: check "fmt " wherever it is, and skip every
 *      other chunk (LIST, fact, JUNK, ...) with its pad byte;
 *   3. stop at "data": the samples start right after its 8-byte chunk header
 *      (data_offset: 44 in our files, more in PC-made ones). A size of 0 or
 *      0xFFFFFFFF, or one past the end of the file, becomes "to the end of
 *      the file" (data_size_clamped).
 * So a PC file with extra chunks plays too, from its real first sample. */
storage_result_t wav_parse_header(const uint8_t *buf, size_t buf_len, uint32_t file_size,
                                  wav_header_t *out)
{
    if ((buf == NULL) || (out == NULL))
    {
        return STORAGE_INVALID_ARG;
    }
    if (buf_len > file_size)
    {
        /* buf is the start of the file, so it cannot hold more than the file */
        return STORAGE_INVALID_ARG;
    }
    if (buf_len < WAV_RIFF_HEADER_SIZE)
    {
        /* Truncated header - not even "RIFF" <size> "WAVE" fits */
        return STORAGE_INVALID_ARG;
    }

    if (memcmp(&buf[0], "RIFF", 4) != 0)
    {
        return STORAGE_CORRUPT;
    }
    if (memcmp(&buf[8], "WAVE", 4) != 0)
    {
        return STORAGE_CORRUPT;
    }
    /* The RIFF size at buf[4] is not checked: streaming writers leave 0 or
     * 0xFFFFFFFF there, and nothing below needs it. */

    wav_header_t parsed = {0};
    bool have_fmt = false;
    size_t pos = WAV_RIFF_HEADER_SIZE;      /* next chunk header; never past buf_len */

    /* Each pass either returns or moves pos forward by at least one chunk
     * header, and pos never passes buf_len, so the walk always ends. */
    for (;;)
    {
        if ((buf_len - pos) < WAV_CHUNK_HEADER_SIZE)
        {
            return walk_ran_out(pos, buf_len, file_size);
        }

        const uint8_t *id = &buf[pos];
        const uint32_t size = get_u32_le(&buf[pos + 4U]);
        const size_t body = pos + WAV_CHUNK_HEADER_SIZE;    /* <= buf_len, checked above */

        if (memcmp(id, "data", 4) == 0)
        {
            if (!have_fmt)
            {
                /* Samples before any format (or no fmt chunk at all) */
                return STORAGE_CORRUPT;
            }

            /* body <= buf_len <= file_size, so neither line can wrap. */
            const uint32_t data_offset = (uint32_t)body;
            const uint32_t available = file_size - data_offset;
            uint32_t data_size = size;
            if ((size == 0U) || (size == WAV_SIZE_UNKNOWN) || (size > available))
            {
                /* 0 or 0xFFFFFFFF: a streaming writer never came back to fill
                 * the size in. Larger than the file: the file was cut short.
                 * Either way the samples run to the end of the file. */
                data_size = available;
            }

            parsed.data_size = data_size;
            parsed.data_offset = data_offset;
            parsed.declared_data_size = size;
            parsed.data_size_clamped = (data_size != size);
            *out = parsed;
            return STORAGE_OK;
        }

        /* Any chunk before "data" has to fit in buf, with the pad byte RIFF
         * puts after an odd-sized chunk (size does not count it), or the
         * walk cannot reach the next one. Compared against the room that is
         * left instead of added up, so a size near 0xFFFFFFFF cannot wrap. */
        const size_t room = buf_len - body;
        const uint32_t pad = size & 1U;
        if ((size > room) || (pad > (room - size)))
        {
            return walk_ran_out(pos, buf_len, file_size);
        }

        if (memcmp(id, "fmt ", 4) == 0)
        {
            const storage_result_t result = parse_fmt_chunk(&buf[body], size, &parsed);
            if (result != STORAGE_OK)
            {
                return result;
            }
            have_fmt = true;
        }
        /* Every other chunk (LIST, fact, bext, JUNK, anything unknown) is
         * skipped unread. */

        pos = body + size + pad;
    }
}

uint32_t wav_duration_ms(const wav_header_t *header)
{
    if (header == NULL)
    {
        return 0U;
    }
    if ((header->sample_rate == 0U) || (header->num_channels == 0U))
    {
        return 0U;
    }
    if ((header->bits_per_sample == 0U) || ((header->bits_per_sample % 8U) != 0U))
    {
        return 0U;
    }

    const uint32_t bytes_per_second =
        header->sample_rate *
        (uint32_t)header->num_channels *
        ((uint32_t)header->bits_per_sample / 8U);

    if (bytes_per_second == 0U)
    {
        return 0U;
    }

    /* 64-bit intermediate prevents overflow on long recordings. */
    return (uint32_t)(((uint64_t)header->data_size * 1000U) / (uint64_t)bytes_per_second);
}
